/* global console */
// Copies docs/contribuicoes/contribuicoes.json (F13) into contributions-data.js so the
// prototype can read it from file:// without fetch.
//   node design/prototipo/sync-contributions.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const items = JSON.parse(readFileSync(join(here, '..', '..', 'docs', 'contribuicoes', 'contribuicoes.json'), 'utf8'));
writeFileSync(join(here, 'contributions-data.js'),
  '// Generated by sync-contributions.mjs from docs/contribuicoes/contribuicoes.json. Do not edit by hand.\n/* global window */\n' +
  `window.VN_CONTRIBUTIONS = ${JSON.stringify({ items })};\n`);
console.log(`${items.length} contributions`);
